(() => {
  'use strict';
  const canvas = document.getElementById('game'), ctx = canvas.getContext('2d');
  const W = 960, H = 600;
  let screen = 'menu', active = 0, last = performance.now(), soundOn = true, audio;
  let pointer = {x: 0, y: 0, down: false}, keys = {}, particles = [], game = null;
  const names = ['DRIP DROP', 'FOMNP FRENZY', 'CLOUD CLIMBER'];
  const bestKey = 'dripdrop-fomnp-best-v1';
  let bests;
  try { bests = JSON.parse(localStorage.getItem(bestKey) || '[0,0,0]'); } catch { bests = [0,0,0]; }
  const C = {aqua:'#65e8d1',pink:'#fb647d',yellow:'#ffd86d',blue:'#7da7ff',cream:'#fff7e8',ink:'#111421'};
  function rounded(x,y,w,h,r,fill,stroke,lw=1) { ctx.beginPath(); ctx.roundRect(x,y,w,h,r); if(fill){ctx.fillStyle=fill;ctx.fill()} if(stroke){ctx.lineWidth=lw;ctx.strokeStyle=stroke;ctx.stroke()} }
  function text(s,x,y,size=16,color=C.cream,font='Bungee',align='left') { ctx.fillStyle=color;ctx.font=`${size}px ${font}`;ctx.textAlign=align;ctx.textBaseline='middle';ctx.fillText(s,x,y); }
  function line(x1,y1,x2,y2,color='#ffffff22',width=1) { ctx.beginPath();ctx.moveTo(x1,y1);ctx.lineTo(x2,y2);ctx.strokeStyle=color;ctx.lineWidth=width;ctx.stroke(); }
  function circle(x,y,r,fill,stroke) { ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);if(fill){ctx.fillStyle=fill;ctx.fill()}if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=2;ctx.stroke()} }
  function sound(freq=440,dur=.07,type='sine') { if(!soundOn)return;try{audio ||= new (window.AudioContext||window.webkitAudioContext)();const o=audio.createOscillator(),g=audio.createGain();o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(.055,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+dur);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+dur)}catch{} }
  function announce(s) { document.getElementById('announcement').textContent=s; }
  function initParticles() { particles=Array.from({length:44},()=>({x:Math.random()*W,y:Math.random()*H,r:1+Math.random()*2,spd:8+Math.random()*20,a:.12+Math.random()*.32,phase:Math.random()*8})); }
  function background(dt=0) { ctx.fillStyle='#151a2a';ctx.fillRect(0,0,W,H);const g=ctx.createRadialGradient(490,200,40,490,300,620);g.addColorStop(0,'#273149');g.addColorStop(1,'#151a2a');ctx.fillStyle=g;ctx.fillRect(0,0,W,H);for(const p of particles){p.y-=p.spd*dt;if(p.y<0){p.y=H;p.x=Math.random()*W}ctx.globalAlpha=p.a*(.7+.3*Math.sin(p.phase+=dt));circle(p.x,p.y,p.r,'#b7d8ee')}ctx.globalAlpha=1; }
  function drip(x,y,s,color=C.aqua) { ctx.save();ctx.translate(x,y);ctx.scale(s,s);ctx.beginPath();ctx.moveTo(0,-17);ctx.bezierCurveTo(-3,-8,-12,1,-12,8);ctx.arc(0,7,12,Math.PI,0);ctx.bezierCurveTo(12,1,3,-8,0,-17);ctx.closePath();ctx.fillStyle=color;ctx.fill();ctx.beginPath();ctx.ellipse(-4,7,2.4,4,-.4,0,Math.PI*2);ctx.fillStyle='#ffffff77';ctx.fill();ctx.restore(); }
  function drawCloud(x,y,s,color='#fff7e8') { ctx.save();ctx.translate(x,y);ctx.scale(s,s);ctx.beginPath();ctx.arc(-17,5,12,Math.PI*.9,Math.PI*1.95);ctx.arc(-4,-5,17,Math.PI,Math.PI*1.9);ctx.arc(12,0,13,Math.PI*1.2,Math.PI*2);ctx.arc(19,7,10,-Math.PI/2,Math.PI/2);ctx.lineTo(-17,17);ctx.closePath();ctx.fillStyle=color;ctx.fill();ctx.restore(); }
  function drawBlob(x,y,r,color,t=0) { ctx.save();ctx.translate(x,y);const wob=Math.sin(t*7+x)*.06;ctx.scale(1+wob,1-wob);circle(0,0,r,color);circle(-r*.34,-r*.1,Math.max(1,r*.105),'#263041');circle(r*.34,-r*.1,Math.max(1,r*.105),'#263041');ctx.beginPath();ctx.arc(0,r*.18,r*.19,.15,Math.PI-.15);ctx.strokeStyle='#263041';ctx.lineWidth=Math.max(1.5,r*.09);ctx.stroke();ctx.restore(); }
  function drawMenu() {
    background();ctx.fillStyle='#f7f0dd';ctx.globalAlpha=.035;for(let i=0;i<18;i++)ctx.fillRect(0,i*35,W,1);ctx.globalAlpha=1;
    rounded(38,35,142,24,12,C.aqua);text('A DRIPDROP ORIGINAL',109,47,9,C.ink,'Lato','center');text('VOL. 01  ·  2026',920,47,10,'#9ba3b8','Lato','right');
    text('PRESENTS',480,100,13,'#a4abc0','Lato','center');text('FOMNP',480,164,64,C.cream,'Bungee','center');text('CUMPILATION!!',480,221,47,C.pink,'Bungee','center');
    ctx.save();ctx.translate(480,256);ctx.rotate(-.045);rounded(-109,-14,218,29,6,C.yellow);text('THREE GAMES. ZERO EXPLANATION.',0,1,11,C.ink,'Lato','center');ctx.restore();
    const cards=[{x:38,color:C.aqua,tag:'CATCH & DODGE',title:names[0],desc:['Catch 12 clean drops.','Watch for the grumps.'],icon:0},{x:338,color:C.pink,tag:'TAP THE GOOD ONES',title:names[1],desc:['Pop 18 happy fomps.','Leave the grumps alone.'],icon:1},{x:638,color:C.yellow,tag:'JUMP & COLLECT',title:names[2],desc:['Find 7 sky sparks.','Try not to fall.'],icon:2}];
    for(let i=0;i<cards.length;i++){const c=cards[i],y=301,w=284,h=210,hov=pointer.x>c.x&&pointer.x<c.x+w&&pointer.y>y&&pointer.y<y+h;rounded(c.x,y,w,h,13,hov?'#303850':'#20283a',hov?c.color:'#343c52',hov?2:1);rounded(c.x+14,y+14,52,52,14,c.color);if(c.icon===0)drip(c.x+40,y+41,.75,'#17303a');if(c.icon===1)drawBlob(c.x+40,y+41,18,C.cream,0);if(c.icon===2)drawCloud(c.x+40,y+42,.68,C.ink);text(c.tag,c.x+78,y+24,9,'#a6adc0','Lato');text(c.title,c.x+17,y+91,18,C.cream,'Bungee');text(c.desc[0],c.x+17,y+119,12,'#b9bfd0','Lato');text(c.desc[1],c.x+17,y+139,12,'#b9bfd0','Lato');rounded(c.x+16,y+164,252,31,8,hov?c.color:'#2b3449');text('PLAY  ↗',c.x+31,y+179,11,hov?C.ink:C.cream,'Lato');text(`BEST ${bests[i]||0}`,c.x+251,y+179,9,hov?C.ink:'#8f99ae','Lato','right');text(`0${i+1}`,c.x+267,y+26,9,'#69748e','Lato','right');}
    text('PICK YOUR POISON',480,543,10,'#8e98ac','Lato','center');text('1   —   2   —   3',480,569,11,'#abb4c9','Lato','center');text('OR CLICK A CABINET',480,586,8,'#69748a','Lato','center');
  }
  function startGame(id) { active=id;screen='game';game={score:0,time:id===1?35:id===0?42:0,lives:3,items:[],spawn:.5,elapsed:0,paused:false,misses:0,player:{x:480,y:500,vx:0,vy:0,ground:false,face:1},stars:[],platforms:[]};if(id===2){game.platforms=[{x:70,y:535,w:820},{x:112,y:438,w:190},{x:390,y:360,w:174},{x:660,y:278,w:190},{x:301,y:213,w:176},{x:72,y:309,w:132},{x:540,y:165,w:145}];game.stars=[[250,415],[441,337],[714,255],[117,286],[361,190],[593,142],[807,415],[513,338],[520,143]].map(([x,y],i)=>({x,y,got:false,phase:i}));game.player.x=115;game.player.y=510;game.player.ground=true;}sound(520,.09);announce(names[id]+' started'); }
  function startByIndex(i) { startGame(i); }
  function saveBest() { if(game&&game.score>(bests[active]||0)){bests[active]=game.score;localStorage.setItem(bestKey,JSON.stringify(bests));} }
  function finish(won) { if(screen==='over')return;screen='over';game.won=won;saveBest();sound(won?760:150,.24,won?'sine':'triangle');announce(won?'You won '+names[active]:'Game over in '+names[active]); }
  function movePlayerTo(x) { if(game)game.player.x=Math.max(88,Math.min(872,x)); }
  function update(dt) {
    if(screen!=='game'||game.paused)return;game.elapsed+=dt;
    if(active===0){game.time-=dt;game.spawn-=dt;if(game.spawn<=0){game.spawn=.72+Math.random()*.32;game.items.push({x:92+Math.random()*776,y:155,r:12+Math.random()*4,bad:Math.random()<.22,vy:155+Math.random()*95,spin:Math.random()*6});}if(pointer.down)movePlayerTo(pointer.x);else{const dir=(keys.ArrowRight||keys.d?1:0)-(keys.ArrowLeft||keys.a?1:0);game.player.x=Math.max(100,Math.min(860,game.player.x+dir*430*dt));}for(const it of game.items){it.y+=it.vy*dt;it.spin+=dt*3;if(it.y>511&&it.y<548&&Math.abs(it.x-game.player.x)<it.r+42){it.caught=true;if(it.bad){game.lives--;sound(130,.12,'square');}else{game.score++;sound(600+game.score*15,.045);}}if(it.y>566&&!it.bad){it.missed=true;game.misses++;if(game.misses%4===0)game.lives--;}}game.items=game.items.filter(i=>!i.caught&&!i.missed&&i.y<585);if(game.score>=12)finish(true);else if(game.lives<=0||game.time<=0)finish(false);}
    if(active===1){game.time-=dt;game.spawn-=dt;if(game.spawn<=0){game.spawn=.52+Math.random()*.3;game.items.push({x:95+Math.random()*770,y:225+Math.random()*260,r:23+Math.random()*14,bad:Math.random()<.24,ttl:1.55+Math.random()*.5,phase:Math.random()*8,scale:0});}for(const it of game.items){it.ttl-=dt;it.phase+=dt*5;it.scale=Math.min(1,it.scale+dt*4);if(it.ttl<=0){it.gone=true;if(!it.bad)game.misses++;}}game.items=game.items.filter(i=>!i.gone);if(game.score>=18)finish(true);else if(game.time<=0)finish(false);}
    if(active===2){const p=game.player,dir=(keys.ArrowRight||keys.d?1:0)-(keys.ArrowLeft||keys.a?1:0);p.vx=dir*260;if(dir)p.face=dir;p.x=Math.max(82,Math.min(878,p.x+p.vx*dt));if((keys.ArrowUp||keys[' ']||keys.w||keys.jump)&&p.ground){p.vy=-485;p.ground=false;keys.jump=false;sound(330,.07);}const oldY=p.y;p.vy+=1040*dt;p.y+=p.vy*dt;p.ground=false;if(p.vy>=0)for(const plat of game.platforms){if(oldY+19<=plat.y&&p.y+19>=plat.y&&p.x>plat.x-12&&p.x<plat.x+plat.w+12){p.y=plat.y-19;p.vy=0;p.ground=true;break;}}for(const star of game.stars){if(!star.got&&Math.hypot(p.x-star.x,p.y-star.y)<29){star.got=true;game.score++;sound(760+game.score*30,.08);}}if(p.y>630){game.lives--;p.x=115;p.y=510;p.vy=0;p.ground=false;sound(130,.15,'triangle');if(game.lives<=0)finish(false);}if(game.score>=7)finish(true);}
  }
  initParticles();

